// ─── File: src/main/java/com/bank/risk/service/RiskCalculationService.java ───
package com.bank.risk.service;

import com.bank.risk.dto.RiskReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

@Service
@Slf4j
public class RiskCalculationService {

    @Value("${risk.portfolio-size:10000}")
    private int portfolioSize;

    @Value("${risk.custom-pool-threads:4}")
    private int customPoolThreads;

    // Simulated CPU-intensive calculation
    private double calculateVaR(int positionId) {
        // Simulate Monte Carlo — CPU work
        double sum = 0;
        for (int i = 0; i < 1000; i++) {
            sum += Math.sin(positionId * 0.001 + i) * Math.cos(i * 0.002);
        }
        return sum;
    }

    // ═══ SEQUENTIAL — baseline ═══
    public RiskReport calculateSequential() {
        List<Integer> positions = IntStream.rangeClosed(1, portfolioSize).boxed().toList();

        long start = System.nanoTime();

        List<String> results = positions.stream()
            .map(id -> "POS-" + id + ": VaR=" + String.format("%.2f", calculateVaR(id)))
            .toList();

        long duration = (System.nanoTime() - start) / 1_000_000;
        log.info("[SEQUENTIAL] {} positions in {}ms", portfolioSize, duration);

        return new RiskReport("SEQUENTIAL", portfolioSize, duration, 1.0,
            true, results.subList(0, Math.min(5, results.size())),
            "Single thread. Ordered. Baseline for comparison.");
    }

    // ═══ PARALLEL — commonPool ═══
    public RiskReport calculateParallel() {
        List<Integer> positions = IntStream.rangeClosed(1, portfolioSize).boxed().toList();

        long start = System.nanoTime();

        List<String> results = positions.parallelStream()
            .map(id -> "POS-" + id + ": VaR=" + String.format("%.2f", calculateVaR(id)))
            .toList();  // toList() preserves encounter order even in parallel

        long duration = (System.nanoTime() - start) / 1_000_000;
        log.info("[PARALLEL commonPool] {} positions in {}ms (pool={})",
            portfolioSize, duration, ForkJoinPool.commonPool().getParallelism());

        return new RiskReport("PARALLEL (commonPool)", portfolioSize, duration,
            0, true, results.subList(0, Math.min(5, results.size())),
            "ForkJoinPool.commonPool parallelism=" + ForkJoinPool.commonPool().getParallelism()
            + ". toList() preserves order. Shared pool — may starve other streams.");
    }

    // ═══ PARALLEL — custom ForkJoinPool (avoids starvation) ═══
    public RiskReport calculateWithCustomPool() throws Exception {
        List<Integer> positions = IntStream.rangeClosed(1, portfolioSize).boxed().toList();

        ForkJoinPool customPool = new ForkJoinPool(customPoolThreads);
        long start = System.nanoTime();

        try {
            List<String> results = customPool.submit(() ->
                positions.parallelStream()
                    .map(id -> "POS-" + id + ": VaR=" + String.format("%.2f", calculateVaR(id)))
                    .toList()
            ).get();

            long duration = (System.nanoTime() - start) / 1_000_000;
            log.info("[PARALLEL customPool({})] {} positions in {}ms",
                customPoolThreads, portfolioSize, duration);

            return new RiskReport("PARALLEL (customPool=" + customPoolThreads + ")",
                portfolioSize, duration, 0, true,
                results.subList(0, Math.min(5, results.size())),
                "Dedicated ForkJoinPool with " + customPoolThreads + " threads. " +
                "Does NOT use commonPool → no starvation of other services.");
        } finally {
            customPool.shutdown();
        }
    }

    // ═══ ORDERING caveat — forEach vs forEachOrdered ═══
    public RiskReport demonstrateOrdering() {
        List<Integer> positions = IntStream.rangeClosed(1, 20).boxed().toList();

        // forEach: SCRAMBLED order
        List<String> forEachOrder = Collections.synchronizedList(new ArrayList<>());
        positions.parallelStream().forEach(id -> forEachOrder.add("POS-" + id));

        // forEachOrdered: PRESERVED order
        List<String> orderedOrder = Collections.synchronizedList(new ArrayList<>());
        positions.parallelStream().forEachOrdered(id -> orderedOrder.add("POS-" + id));

        // Check if forEach result is in natural order
        boolean forEachIsOrdered = true;
        for (int i = 1; i < forEachOrder.size(); i++) {
            int prev = Integer.parseInt(forEachOrder.get(i-1).replace("POS-",""));
            int curr = Integer.parseInt(forEachOrder.get(i).replace("POS-",""));
            if (curr < prev) { forEachIsOrdered = false; break; }
        }

        return new RiskReport("ORDERING_DEMO", 20, 0, 0,
            !forEachIsOrdered,  // true means forEach WAS scrambled (expected)
            List.of("forEach: " + forEachOrder.subList(0, 10),
                    "forEachOrdered: " + orderedOrder.subList(0, 10)),
            "forEach: " + (forEachIsOrdered ? "ordered (lucky)" : "SCRAMBLED (expected)")
            + " | forEachOrdered: always ordered but slower");
    }
}
